import sys

def min_operations_to_zero(v):
    if v == 0:
        return 0
    operations = 0
    while v != 0:
        if v % 2 == 0:
            v //= 2
        else:
            v = (v + 1) % 32768
        operations += 1
    return operations

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    result = [min_operations_to_zero(ai) for ai in a]

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
